let wanted=false,lock=null;
async function acquire(){if(!wanted||document.hidden)return;try{if(!navigator.wakeLock)throw Error('Use this tablet’s screen timeout setting.');lock=await navigator.wakeLock.request('screen');lock.addEventListener('release',()=>{lock=null;status('Screen may sleep. Tap Keep screen awake again if needed.');});status('Screen stays awake while this page is visible.');}catch(e){status(e.message||'Screen wake lock unavailable. Check the tablet’s display settings.');}}
function status(message){const node=document.querySelector('#counter-awake-status');if(node)node.textContent=message;}
export function bindCounterAwake(){const b=document.querySelector('#counter-awake');if(!b)return;b.textContent=wanted?'Allow screen to sleep':'Keep screen awake';b.onclick=async()=>{wanted=!wanted;b.textContent=wanted?'Allow screen to sleep':'Keep screen awake';if(wanted)await acquire();else{await lock?.release();lock=null;status('Normal screen timeout restored.');}};if(wanted)status(lock?'Screen stays awake while this page is visible.':'Screen wake lock requested.');}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&wanted&&!lock)acquire();});
